def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    return np.where(mask, -(bins - item), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    remaining_space = bins - item
    extra_items = remaining_space // item
    return np.where(mask, extra_items, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    mask = bins >= item
    return np.where(mask, bins - item, -1.0)
